from datetime import date, timedelta

def is_business_day(d: date, holidays=()) -> bool:
    if d.weekday() >= 5:
        return False
    return d not in set(holidays)

def adjust_business_day(d: date, holidays=(), convention: str = "modified_following") -> date:
    if not isinstance(convention, str):
        raise ValueError("unknown convention")
    norm = convention.lower()
    if norm not in ("following", "modified_following", "preceding"):
        raise ValueError("unknown convention")
    hol = set(holidays)
    if norm == "following":
        if is_business_day(d, hol):
            return d
        cur = d + timedelta(days=1)
        while not is_business_day(cur, hol):
            cur += timedelta(days=1)
        return cur
    if norm == "preceding":
        if is_business_day(d, hol):
            return d
        cur = d - timedelta(days=1)
        while not is_business_day(cur, hol):
            cur -= timedelta(days=1)
        return cur
    # modified_following
    if is_business_day(d, hol):
        return d
    fwd = d + timedelta(days=1)
    while not is_business_day(fwd, hol):
        fwd += timedelta(days=1)
    if (fwd.year, fwd.month) != (d.year, d.month):
        prev = d - timedelta(days=1)
        while not is_business_day(prev, hol):
            prev -= timedelta(days=1)
        return prev
    return fwd

def add_business_days(start: date, n: int, holidays=()) -> date:
    if isinstance(n, bool) or not isinstance(n, int):
        raise ValueError("n must be int")
    if n == 0:
        return start
    hol = set(holidays)
    cur = start
    step = timedelta(days=1) if n > 0 else timedelta(days=-1)
    counted = 0
    target = n if n > 0 else -n
    while counted < target:
        cur = cur + step
        if is_business_day(cur, hol):
            counted += 1
    return cur
